/**
 * Validate one identity.v1 fixture against the generated schema.
 *
 * Generated by scripts/generate_bindings.py. Do not edit.
 *
 * JavaScript numbers cannot hold every integer the schema allows. This file
 * checks each number token with BigInt, then hands Ajv a safe spelling.
 * `1.0` stays acceptable: draft 2020-12 treats it as the integer 1.
 */
import Ajv2020 from "ajv/dist/2020.js";
import { readFileSync } from "node:fs";
import schema from "./schema.json" with { type: "json" };

const I64_MIN = -9223372036854775808n;
const I64_MAX = 9223372036854775807n;
const U64_MAX = 18446744073709551615n;
const SAFE = 9007199254740991n;
const TIMESTAMPS = new Set(["issued_at", "expires_at", "ended_at"]);

type SchemaDocument = {
  $schema: string;
  $defs: Record<string, unknown>;
};

const documentSchema = schema as SchemaDocument;

function bounds(key: string | null): [bigint, bigint] {
  if (key !== null && TIMESTAMPS.has(key)) {
    return [I64_MIN, I64_MAX];
  }
  return [I64_MIN, U64_MAX];
}

function integerValue(token: string): bigint | null {
  const matched = /^(-?)(\d+)(?:\.(\d+))?(?:[eE]([+-]?\d+))?$/.exec(token);
  if (matched === null) {
    return null;
  }
  const whole = matched[2];
  const frac = matched[3];
  const expText = matched[4];
  if (frac === undefined && expText === undefined && whole.length > 1 && whole.startsWith("0")) {
    return null;
  }
  const sign = matched[1] === "-" ? -1n : 1n;
  const exp = expText === undefined ? 0 : Number(expText);
  if (!Number.isSafeInteger(exp)) {
    return null;
  }
  const digits = (whole + (frac ?? "")).replace(/^0+/, "") || "0";
  const shift = exp - (frac ?? "").length;
  if (shift >= 0) {
    return sign * BigInt(digits) * 10n ** BigInt(shift);
  }
  const cut = -shift;
  if (digits.length <= cut) {
    return /^0+$/.test(digits) ? 0n : null;
  }
  if (!/^0+$/.test(digits.slice(digits.length - cut))) {
    return null;
  }
  const head = digits.slice(0, digits.length - cut).replace(/^0+/, "") || "0";
  return sign * BigInt(head);
}

function sanitize(raw: string): string | null {
  let out = "";
  let index = 0;
  let lastKey: string | null = null;
  let pendingKey: string | null = null;
  while (index < raw.length) {
    const char = raw[index];
    if (char === '"') {
      const start = index;
      index += 1;
      let text = "";
      while (index < raw.length) {
        const next = raw[index];
        if (next === "\\") {
          text += next + (raw[index + 1] ?? "");
          index += 2;
          continue;
        }
        if (next === '"') {
          index += 1;
          break;
        }
        text += next;
        index += 1;
      }
      out += raw.slice(start, index);
      lastKey = text;
      continue;
    }
    if (char === ":") {
      pendingKey = lastKey;
      out += char;
      index += 1;
      continue;
    }
    if (char === "-" || (char >= "0" && char <= "9")) {
      const start = index;
      if (char === "-") {
        index += 1;
      }
      while (index < raw.length && /[0-9.eE+-]/.test(raw[index])) {
        index += 1;
      }
      const token = raw.slice(start, index);
      const value = integerValue(token);
      const key = pendingKey;
      pendingKey = null;
      if (value === null) {
        return null;
      }
      const [low, high] = bounds(key);
      if (value < low || value > high) {
        return null;
      }
      const magnitude = value < 0n ? -value : value;
      out += magnitude > SAFE ? "0" : token;
      continue;
    }
    if (char !== " " && char !== "\n" && char !== "\r" && char !== "\t") {
      pendingKey = null;
    }
    out += char;
    index += 1;
  }
  return out;
}

const ajv = new Ajv2020({ strict: false, allErrors: true });
const validators = new Map<string, (data: unknown) => boolean>();

function validatorFor(kind: string): (data: unknown) => boolean {
  const cached = validators.get(kind);
  if (cached !== undefined) {
    return cached;
  }
  const validate = ajv.compile({
    $schema: documentSchema.$schema,
    $defs: documentSchema.$defs,
    $ref: `#/$defs/${kind}`,
  });
  const wrapped = (data: unknown) => validate(data) === true;
  validators.set(kind, wrapped);
  return wrapped;
}

const raw = readFileSync(process.argv[2], "utf8");
const sanitized = sanitize(raw);
if (sanitized === null) {
  console.log("reject");
} else {
  try {
    const document = JSON.parse(sanitized) as { kind: string; value: unknown };
    console.log(validatorFor(document.kind)(document.value) ? "accept" : "reject");
  } catch {
    console.log("reject");
  }
}
